function money(value) {
  const n = Number(value || 0)
  return n > 0 ? '$' + n.toFixed(2) : 'pendiente de confirmar'
}

function digitsOnly(value) {
  const raw = String(value || '').replace(/\D/g, '')
  if (!raw) return ''
  if (raw.length === 10) return '1' + raw
  if (raw.length === 11 && raw.startsWith('1')) return raw
  return raw
}

function cadenceLabel(step) {
  const labels = {
    formal_amable: 'Aviso formal amable',
    recordatorio_corto: 'Recordatorio corto',
    revision_interna: 'Revision interna de cuenta',
    ultimo_aviso_legal: 'Ultimo aviso legal',
  }
  return labels[step] || null
}

function buildAutomationKey(caseId, campaignType, cadenceStep, localDate, channel) {
  return [caseId, campaignType, cadenceStep, localDate, channel].join(':')
}

function buildMessage(target, channel, cadenceStep) {
  const nombre = target.nombre || 'Cliente'
  const cuenta = target.cuenta_hycite || 'S/N'
  const monto = money(target.monto_cargo_vuelta)
  const fecha = target.fecha_cargo_vuelta || 'No registrada'
  const stop = channel === 'whatsapp'
    ? '\n\nResponda ALTO para no recibir mensajes por este medio.'
    : '\n\nSi prefiere no recibir mensajes por este medio, responda ALTO.'
  const variants = {
    formal_amable:
      'Estimado/a ' + nombre + ',\n\n' +
      'Le contactamos del equipo de resolucion de Connection Worldwide Group sobre su cuenta Royal Prestige / Hy-Cite #' + cuenta + '.\n\n' +
      'Balance pendiente de regularizar: ' + monto + '\n' +
      'Fecha de referencia: ' + fecha + '\n\n' +
      'Queremos revisar opciones de pago y ayudarle a llegar a un acuerdo comodo antes de que el proceso avance internamente. ' +
      'Puede responder a este mensaje o contactar a Patricia Caicedo al (786) 291-3042.' + stop,
    recordatorio_corto:
      'Hola ' + nombre + ', le damos seguimiento a su cuenta Royal Prestige / Hy-Cite #' + cuenta + '.\n\n' +
      'Tenemos opciones de pago disponibles para regularizar el balance de ' + monto + '. ' +
      'Responda a este mensaje y coordinamos un acuerdo comodo.' + stop,
    revision_interna:
      'Estimado/a ' + nombre + ', su cuenta #' + cuenta + ' continua en revision interna por balance pendiente de ' + monto + '.\n\n' +
      'Nuestro equipo de resolucion quiere hablar con usted para documentar una alternativa de pago antes de escalar el seguimiento operativo.' + stop,
    ultimo_aviso_legal:
      'Hola ' + nombre + ', este es nuestro ultimo aviso automatico sobre la cuenta Royal Prestige / Hy-Cite #' + cuenta + '.\n\n' +
      'Balance pendiente de regularizar: ' + monto + '\n' +
      'Fecha de referencia: ' + fecha + '\n\n' +
      'Si no logramos documentar una alternativa de pago, el caso puede avanzar a la siguiente revision operativa/legal. ' +
      'Comuniquese hoy con Patricia Caicedo al (786) 291-3042 o responda este mensaje.' + stop,
  }
  return variants[cadenceStep] || null
}

const out = []
for (const item of $input.all()) {
  const t = item.json
  const cadenceStep = typeof t.cadence_step === 'string' ? t.cadence_step.trim() : ''
  const cadenceStepLabel = cadenceLabel(cadenceStep)
  if (!cadenceStep || !cadenceStepLabel) {
    continue
  }

  const ownerId = $env.COBRANZA_OWNER_ID || t.owner_id
  const orgId = t.org_id || $env.FLOWSUITE_ORG_ID
  const scheduledFor = new Date(Date.now() - 1000).toISOString()
  const localDate = $now.toISODate()
  const campaignType = 'cargo_vuelta_dfp_auto'
  const emailMessage = buildMessage(t, 'email', cadenceStep)
  const whatsappMessage = buildMessage(t, 'whatsapp', cadenceStep)
  const phone = digitsOnly(t.telefono || t.telefono_casa)
  const keyBase = campaignType + '; case_id=' + t.case_id + '; cadence_step=' + cadenceStep + '; local_date=' + localDate

  out.push({
    json: {
      ...t,
      cadence: {
        step: cadenceStep,
        label: cadenceStepLabel,
      },
      provider: String($env.WHATSAPP_PROVIDER || '').toLowerCase(),
      normalized_phone: phone,
      emailOutbox: t.email && emailMessage ? {
        owner_id: ownerId,
        org_id: orgId,
        contact_tipo: 'cliente',
        contact_id: t.cliente_id,
        contexto_tipo: 'cobranza',
        canal: 'email',
        destinatario: t.email,
        asunto: 'Revision de cuenta Royal Prestige #' + (t.cuenta_hycite || 'S/N'),
        mensaje: emailMessage,
        mensaje_resuelto: emailMessage,
        cc_emails: $env.COBRANZA_CC_EMAIL ? [$env.COBRANZA_CC_EMAIL] : null,
        from_name: 'Equipo de Resolucion CWG',
        dispatch_provider: 'n8n',
        cobranza_automation_key: buildAutomationKey(t.case_id, campaignType, cadenceStep, localDate, 'email'),
        status: 'programado',
        scheduled_for: scheduledFor,
      } : null,
      whatsappOutbox: phone && whatsappMessage ? {
        owner_id: ownerId,
        org_id: orgId,
        contact_tipo: 'cliente',
        contact_id: t.cliente_id,
        contexto_tipo: 'cobranza',
        canal: 'whatsapp',
        destinatario: phone,
        mensaje: whatsappMessage,
        mensaje_resuelto: whatsappMessage,
        dispatch_provider: 'n8n',
        cobranza_automation_key: buildAutomationKey(t.case_id, campaignType, cadenceStep, localDate, 'whatsapp'),
        status: 'programado',
        scheduled_for: scheduledFor,
      } : null,
      gestion: {
        org_id: orgId,
        cliente_id: t.cliente_id,
        case_id: t.case_id,
        tipo_gestion: 'seguimiento',
        resultado: 'recordatorio_automatico_cargo_vuelta',
        notas: 'Recordatorio automatico de cargo de vuelta preparado. ' + cadenceStepLabel + '. ' + keyBase,
      },
    },
  })
}

return out

