    outbox: row,
    provider: 'whatsapp_cloud_mock',
    provider_message_id: `mock_cloud_${row.id}`,
    request_payload: requestPayload,
    response_payload: { ok: true, mock: true, provider: 'whatsapp_cloud', messages: [{ id: `mock_cloud_${row.id}` }] }
  }};
});

